    double b2, dot_b_bdot, parallel_coeff, norm_m;

    // 1. Validate inputs
    if ((field_body_t == NULL) || (field_rate_t_s == NULL) || (command == NULL)) {
        command->command = (adcs_vec3_t){0, 0, 0};
        command->saturated_axes = 0U;
        return ADCS_E_NULL;
    }
    if ((!adcs_is_finite_vec3(field_body_t)) || (!adcs_is_finite_vec3(field_rate_t_s)) ||
        (!isfinite(normalized_gain_nm_s_t)) || (!isfinite(max_dipole_a_m2)) ||
        (normalized_gain_nm_s_t < 0.0) || (max_dipole_a_m2 < 0.0)) {
        command->command = (adcs_vec3_t){0, 0, 0};
        command->saturated_axes = 0U;
        return ADCS_E_RANGE;
    }

    // 2. Calculate B^2 and check for degeneracy
    b2 = adcs_vec3_dot(field_body_t, field_body_t);
    if (b2 <= ADCS_EPS_NORM * ADCS_EPS_NORM) {
        command->command = (adcs_vec3_t){0, 0, 0};
        command->saturated_axes = 0U;
        return ADCS_E_DEGENERATE;
    }

    // 3. Project rate onto perpendicular component: remove rate_parallel
    // rate_parallel = (Bdot . B) * B / B^2
    // Bdot_perp = Bdot - rate_parallel
    double dot_b_bdot = adcs_vec3_dot(field_rate_t_s, field_body_t);
    double scale_parallel = dot_b_bdot / b2;

    adcs_vec3_t rate_parallel = adcs_vec3_scale(field_body_t, scale_parallel);
    adcs_vec3_t rate_perp = adcs_vec3_sub(field_rate_t_s, &rate_parallel);

    // 4. Unconstrained dipole: m = -gain * rate_perp / B^2
    // Note: The formula says m = -gain * rate_perp / b2.
    // We can combine scaling: m = rate_perp * (-gain / b2)
    double gain_over_b2 = -normalized_gain_nm_s_t / b2;
    m_unscaled = adcs_vec3_scale(&rate_perp, gain_over_b2);

    // 5. Apply Euclidean-norm limit
    norm_m = adcs_vec3_norm(&m_unscaled);
    command->saturated_axes = 0U;

    if (norm_m > max_dipole_a_m2) {
        // Scale to preserve direction but limit magnitude
        double scale_factor = max_dipole_a_m2 / norm_m;
        command->command = adcs_vec3_scale(&m_unscaled, scale_factor);
        command->saturated_axes = 7U; // Mask set iff scaled
    } else {
        command->command = m_unscaled;
    }

    return ADCS_OK;
}

